// The real implementation, published as a CommonJS whole-module default --
// an ANONYMOUS function expression, exactly as qs/lib/parse.js publishes
// the symbol its advisory calls `parse`. Its canonical export name here is
// "default"; the advisory-facing name is "vulnerable". They are genuinely
// different names, which is the whole difficulty.
module.exports = function (input) {
  return "onehop-vulnerable:" + input;
};
